mapper.select:
SELECT * FROM (
    SELECT A.*, ROWNUM AS RNUM FROM (
        SELECT X.* FROM (
            SELECT 
                A.DEPT_ID,
                B.DEPT_NM,
                SUM(A.TOTAL_CNT) AS TOTAL_SEND_CNT,
                SUM(A.SUCCESS_CNT) AS TOTAL_SUCCESS_CNT,
                SUM(A.FAIL_CNT) AS TOTAL_FAIL_CNT
            FROM TB_SMS_HISTORY A
            JOIN TB_DEPT B ON A.DEPT_ID = B.DEPT_ID
            WHERE 1=1
              AND A.SEND_DT BETWEEN #{startDate} AND #{endDate}
              AND B.DEPT_NM LIKE '%' || #{deptNm} || '%'
            GROUP BY A.DEPT_ID, B.DEPT_NM
            ORDER BY TOTAL_SEND_CNT DESC
        ) X

    ) A WHERE ROWNUM <= #{offset} + #{size}
) WHERE RNUM > #{offset}
